# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
#
# Faithful twin: a plaintext model of the exact encrypted circuit.
#
# The reference computes  risk = 1 - S0^exp(lp - mean)  per sex. The circuit
# uses the identity  S0^exp(z) = exp(-exp(z + ln(-ln S0)))  to fold both
# sexes onto ONE function of one number:
#
#     u    = sum_i w_i * x_i                 (bias slot carries -mean + ln(-ln S0))
#     risk = g(u) = 1 - exp(-exp(u))
#
# Client-side (clear, the patient's own data):
#   range check, ln(age/bmi/sbp), and slot placement by sex and BP treatment,
#   so the server never branches on data.
#
# Slot layout (16 of N/2 slots; every other slot is zero):
#   0..7  male block   [ln age, ln bmi, ln sbp*(1-t), ln sbp*t, smoker, diabetic, 1, 0]
#   8..15 female block (same order)
#   Only the patient's own block is filled; the other block is all zeros.
#
# Server circuit (encrypted):
#   1. ct * w            plaintext weights (incl. bias)          1 level
#   2. rotate-and-sum    rotations 1, 2, 4, 8 -> u in slot 0      0 levels
#   3. ct * e0           mask: zero every slot but 0             1 level
#                        (partial sums in slots 1..15 and the wrapped tail
#                         would land outside the curve's range otherwise)
#   4. g(u)              Chebyshev interpolant on [U_LO, U_HI]   cheb levels
#   5. Compress to one tower for the return trip.
#
# Standard library only.

import math

import reference as ref

BLOCK = 8
N_USED = 2 * BLOCK
ROTATIONS = (1, 2, 4, 8)


def bias(sex):
    c = ref.COEF[sex]
    return -c["group_mean"] + math.log(-math.log(c["baseline_survival"]))


def weights():
    w = [0.0] * N_USED
    for b, sex in enumerate(("male", "female")):
        c = ref.COEF[sex]
        w[b * BLOCK:(b + 1) * BLOCK] = [c["ln_age"], c["ln_bmi"], c["ln_untreated_sbp"],
                                        c["ln_treated_sbp"], c["smoker"], c["diabetes"],
                                        bias(sex), 0.0]
    return w


def pack(sex, age, bmi, sbp, bp_treated, smoker, diabetic):
    """Client-side encoding of one patient (after the bounds check)."""
    if not ref.in_bounds(age, bmi, sbp):
        raise ValueError("input outside the supported range")
    x = [0.0] * N_USED
    ls = math.log(sbp)
    blk = [math.log(age), math.log(bmi), ls * (1 - bp_treated), ls * bp_treated,
           float(smoker), float(diabetic), 1.0, 0.0]
    off = 0 if sex == "male" else BLOCK
    x[off:off + BLOCK] = blk
    return x


def g(u):
    return 1.0 - math.exp(-math.exp(u))


def u_bounds():
    """Provable range of u over the input box: every weight on a log input or
    flag is positive, so u is monotone in each input and the extremes sit at
    the box corners. Unused block -> u = 0, also inside."""
    lo, hi = 0.0, 0.0
    for sex in ("male", "female"):
        c = ref.COEF[sex]
        b = bias(sex)
        a_lo, a_hi = map(math.log, ref.BOUNDS["age"])
        m_lo, m_hi = map(math.log, ref.BOUNDS["bmi"])
        s_lo, s_hi = map(math.log, ref.BOUNDS["sbp"])
        sb = min(c["ln_untreated_sbp"], c["ln_treated_sbp"])
        sB = max(c["ln_untreated_sbp"], c["ln_treated_sbp"])
        lo = min(lo, c["ln_age"] * a_lo + c["ln_bmi"] * m_lo + sb * s_lo + b)
        hi = max(hi, c["ln_age"] * a_hi + c["ln_bmi"] * m_hi + sB * s_hi
                 + c["smoker"] + c["diabetes"] + b)
    return lo, hi


# ---- Chebyshev interpolation, mirroring OpenFHE EvalChebyshevCoefficients ----

def cheb_coeffs(f, a, b, degree):
    n = degree + 1
    xs = [math.cos(math.pi * (k + 0.5) / n) for k in range(n)]
    fx = [f((b - a) / 2.0 * x + (a + b) / 2.0) for x in xs]
    return [2.0 / n * sum(fx[k] * math.cos(j * math.pi * (k + 0.5) / n) for k in range(n))
            for j in range(n)]


def cheb_eval(c, a, b, x):
    """sum c_j T_j(y) with c_0 halved (OpenFHE convention), y mapped to [-1,1]."""
    y = (2.0 * x - a - b) / (b - a)
    b1 = b2 = 0.0
    for cj in reversed(c[1:]):
        b1, b2 = 2.0 * y * b1 - b2 + cj, b1
    return y * b1 - b2 + c[0] / 2.0


def cheb_levels(degree):
    """Levels EvalChebyshevFunction consumes under FLEXIBLEAUTO:
    ceil(log2(degree+1)) for the series plus 1 for mapping the input onto
    [-1, 1]. (OpenFHE's FUNCTION_EVALUATION.md table omits that +1; at
    depth 7 the degree-27 circuit fails with "multiplicative depth [7] is
    insufficient", and it runs at depth 8.)"""
    return math.ceil(math.log2(degree + 1)) + 1


# ---- Slot-level simulation of the circuit ----

def quantize(v, scale_bits):
    d = float(1 << scale_bits)
    return [round(t * d) / d for t in v]


def simulate(patient, coeffs, domain, scale_bits=42, slots=64):
    """Run the exact server program on a small cyclic slot vector.

    `slots` stands in for N/2: rotation is cyclic either way, so the wrapped
    partial sums that the mask must kill appear here exactly as on the ring.
    """
    x = quantize(pack(*patient) + [0.0] * (slots - N_USED), scale_bits)
    w = quantize(weights() + [0.0] * (slots - N_USED), scale_bits)
    v = [xi * wi for xi, wi in zip(x, w)]
    for r in ROTATIONS:                       # EvalRotate(ct, r): slot i <- slot i+r
        v = [v[i] + v[(i + r) % slots] for i in range(slots)]
    v = [v[0]] + [0.0] * (slots - 1)          # mask e0
    out = [cheb_eval(coeffs, *domain, t) for t in v]
    return out[0], max(abs(t) for t in out[1:])


def depth(degree):
    return 1 + 1 + cheb_levels(degree)


def sweep(degrees=(7, 13, 21, 27, 41, 59), margin=0.5):
    lo, hi = u_bounds()
    dom = (math.floor(lo - margin), math.ceil(hi + margin))
    pts = ref.test_patients()
    refs = [ref.risk(*p) for p in pts]
    grid = [dom[0] + (dom[1] - dom[0]) * i / 4000 for i in range(4001)]
    print(f"provable u range over the input box: [{lo:.3f}, {hi:.3f}]  -> domain {dom}")
    print(f"{'degree':>6} {'depth':>5} {'max|err| test (pp)':>19} {'max|err| domain (pp)':>21} {'flips':>5}")
    rows = []
    for d in degrees:
        c = cheb_coeffs(g, *dom, d)
        errs, flips = [], 0
        for p, r in zip(pts, refs):
            t, _ = simulate(p, c, dom, slots=N_USED * 2)
            errs.append(abs(t - r))
            flips += ref.category(t) != ref.category(r)
        gerr = max(abs(cheb_eval(c, *dom, u) - g(u)) for u in grid)
        rows.append((d, depth(d), max(errs) * 100, gerr * 100, flips))
        print(f"{d:6d} {depth(d):5d} {max(errs)*100:19.6f} {gerr*100:21.6f} {flips:5d}")
    return dom, rows


# ---- Frozen design point (approved at the Stage 7 gate) ----

DEGREE = 27
DOMAIN = (-7.0, 3.0)


def emit(data_dir):
    """Write the server's model file and the twin/reference answer key.

    model.txt (server side only): 16 slot weights, the curve's range, degree.
    test_patients.csv: every test patient with the reference and twin risk.
    """
    import csv
    import os
    os.makedirs(data_dir, exist_ok=True)
    with open(os.path.join(data_dir, "model.txt"), "w") as f:
        f.write("# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).\n")
        f.write("# Framingham 2008 office-based (BMI) model, folded for the encrypted circuit.\n")
        f.write("# line 1: 16 slot weights (male block 0..7, female block 8..15)\n")
        f.write("# line 2: risk-curve range lo hi;  line 3: curve degree\n")
        f.write(" ".join(repr(w) for w in weights()) + "\n")
        f.write(f"{DOMAIN[0]!r} {DOMAIN[1]!r}\n{DEGREE}\n")
    c = cheb_coeffs(g, *DOMAIN, DEGREE)
    with open(os.path.join(data_dir, "test_patients.csv"), "w", newline="") as f:
        wr = csv.writer(f)
        wr.writerow(["sex", "age", "bmi", "sbp", "bp_treated", "smoker", "diabetic",
                     "ref_risk", "twin_risk", "ref_band", "twin_band"])
        for p in ref.test_patients():
            r = ref.risk(*p)
            t, _ = simulate(p, c, DOMAIN, slots=N_USED * 2)
            wr.writerow(list(p) + [f"{r:.10f}", f"{t:.10f}", ref.category(r), ref.category(t)])


if __name__ == "__main__":
    import sys
    if len(sys.argv) > 2 and sys.argv[1] == "--emit":
        emit(sys.argv[2])
    else:
        sweep()
